import {ReviewClock} from './auto-advance.mjs';
import {IslandAudio,WordSpeaker,migrateAudioSettings} from './audio.mjs';
import {selectPool} from './engine.mjs';
import {BattleAction} from './battle.mjs';
import {MonsterPark} from './park.mjs';
import {RangerCloud} from './cloud.mjs';
import {MISSION_STAGES,RARITIES,UNLOCKS,CATCH_RATES,STAT_KEYS,monsterStats,quality,rosterSummary,migrateLegacy,reduceGame,canCatch,specialCost,encounterOdds} from './rpg.mjs';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true"><use href="#i-${name}"></use></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageOK=true;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{storageOK=false;return fallback;}}
let settings={mode:'mixed',timed:false,seconds:25,course:'ALL',scope:'all',groupIds:[],sfx:true,music:true,musicVolume:.12,sfxVolume:.65,voiceVolume:1,...migrateAudioSettings(read('wordling-preview-settings-v3',{}))};
function save(){try{localStorage.setItem('wordling-preview-settings-v3',JSON.stringify(settings));if(guest)localStorage.setItem('wordling-preview-save-v3',JSON.stringify(state));}catch{storageOK=false;}}
let data,MONSTERS=[],cloud,state={profile:null,mission:null},alias='',guest=false,view='auth',park=null,parkPage=0,parkReturnView='home',parkWasPaused=false,paused=false,modalPaused=false,round=null,intent='attack',actionBusy=false,networkBusy=false,battleAction=null,remainingMs=0,lastTick=0,waitingForAudio=false,speaking=false,voiceToken=0,audioDeadline,timerId,warehouseFilter='All',warehousePage=0;
const autoAdvance=new ReviewClock();let autoHeld=false,hatchBusy=false,selectedParkId=null,parkBusy=false;
const item=(name,cls='')=>`<img class="item-art ${cls}" src="preview/assets/${name}.png" alt="" aria-hidden="true">`;
if(settings.previewMixVersion!==3){settings.sfxVolume=.65;settings.previewMixVersion=3;}
const sound=new IslandAudio(settings),speaker=new WordSpeaker(sound);
const species=id=>MONSTERS.find(m=>m.id===id),indexOf=id=>MONSTERS.findIndex(m=>m.id===id);
const sprite=(i,cls='')=>{const m=MONSTERS[i];if(!m)return '';const s=m.sprite,x=s.columns===1?0:(s.index%s.columns)/(s.columns-1)*100,y=s.rows===1?0:Math.floor(s.index/s.columns)/(s.rows-1)*100;return `<div class="monster dex-sprite ${cls}" role="img" aria-label="${esc(m.name)}" style="background-image:url('${s.file}');background-size:${s.columns*100}% ${s.rows*100}%;background-position:${x}% ${y}%;--species-color:${m.color}"></div>`;};
const badge=m=>`<span class="rarity rarity-${m.rarity.toLowerCase()}">${m.rarity}</span>`;
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>t.classList.remove('visible'),4500);}
function sfx(kind){sound.effect(kind);}
function stopPark(){park?.destroy();park=null;}
function header(gameHeader=false){document.body.dataset.screen=view;if(gameHeader)return `<header class="play-header"><div class="play-title">${icon('leaf')}<strong>WORDLING <small>ADVENTURE PREVIEW</small></strong></div><button class="pause-button" data-action="pause" aria-label="Pause">${icon('pause')} Pause</button></header>`;return `<header class="base-header"><div class="play-title">${icon('leaf')}<strong>WORDLING <small>ADVENTURE PREVIEW</small></strong></div><nav aria-label="Base menu">${view==='park'?'<button class="secondary-button" data-action="park-back">'+icon('back')+' Back</button>':'<button class="secondary-button" data-action="park">'+icon('park')+' Team Park</button>'}<button class="nav-button" data-action="sound-settings" aria-label="Audio settings">${icon('music')}</button><button class="nav-button" data-action="account" aria-label="Player menu">${icon('book')}</button></nav></header>`;}
function hasActiveMission(){return ['question','result'].includes(state.mission?.phase);}
async function closeMenu(){if(!modal.open)return;modalPaused=false;await new Promise(resolve=>{modal.addEventListener('close',resolve,{once:true});modal.close();});}
function teamOverview(){const p=state.profile;if(!p)return '';const sum=rosterSummary(p,MONSTERS),active=state.mission&&['question','result'].includes(state.mission.phase);return `<section class="team-overview"><div><strong>${esc(guest?'Guest ranger':alias)}</strong><small>${guest?'Local save · not ranked':'Cloud save · synced'} · ${sum.caught} caught · ${sum.unique}/100 species · ${sum.missions} missions</small></div><div class="team-preview">${p.team.map(id=>{const m=p.inventory.find(m=>m.id===id);return `<button data-action="warehouse" title="${esc(species(m.speciesId).name)} Lv.${m.level}">${sprite(indexOf(m.speciesId))}<small>Lv.${m.level}</small></button>`;}).join('')}</div>${active?'<button class="next-button" data-action="resume-mission">Resume mission</button>':''}</section>`;}
function modalHeading(title,description=''){return `<div class="modal-heading"><div><h2>${esc(title)}</h2>${description?`<p>${esc(description)}</p>`:''}</div><button class="close-button" data-action="close-modal" aria-label="Close">${icon('close')}</button></div>`;}
function openModal(content){stopBattleAction();if(view==='game'&&!paused){modalPaused=true;paused=true;stopSpeech();}else if(!modal.open)modalPaused=false;modal.innerHTML=content;if(!modal.open)modal.showModal();}
function stopSpeech(){voiceToken++;speaker.stop();speaking=false;clearTimeout(audioDeadline);$('.audio-button')?.classList.remove('speaking');}
function speak(word,{first=false,onDone=()=>{}}={}){
 stopSpeech();const token=voiceToken,current=round,isQuestion=view==='game'&&round?.phase==='question'&&!paused&&word===round.card.english;let finished=false;
 if(first&&isQuestion)waitingForAudio=true;
 const finish=()=>{if(token!==voiceToken||finished)return;finished=true;speaking=false;$('.audio-button')?.classList.remove('speaking');if(isQuestion&&round===current){waitingForAudio=false;lastTick=Date.now();}clearTimeout(audioDeadline);updateVoiceStatus();onDone();};
 speaking=true;
 speaker.play(word,{onstart:()=>{if(token!==voiceToken)return;speaking=true;$('.audio-button')?.classList.add('speaking');},onend:finish,onerror:()=>{finish();if(first&&isQuestion){waitingForAudio=true;toast('Tap Listen to retry. Your timer is paused.');}}}).catch(finish);
 audioDeadline=setTimeout(()=>{if(token!==voiceToken)return;if(first&&isQuestion){stopSpeech();waitingForAudio=true;toast('Tap Listen to retry. Your timer is paused.');}else finish();},first?20000:8000);
}
function updateVoiceStatus(message){const el=$('#voice-status');if(el)el.textContent=message||(speaker.fallback?'Device American voice · Reload to retry recordings':speaker.manifest?'Jenny · Natural American English · All words loaded':'Loading American voice…');}
async function act(action){if(networkBusy)throw Error('Saving your last move. Please wait.');networkBusy=true;document.body.classList.add('saving');try{state=guest?reduceGame(state,action,data,MONSTERS):await cloud.action(action);save();return state;}catch(e){if(e.status===409){const r=await cloud.me();state=r.state;}throw e;}finally{networkBusy=false;document.body.classList.remove('saving');}}
function renderAuth(){stopPark();stopSpeech();clearInterval(timerId);view='auth';document.body.dataset.screen='auth';app.innerHTML=`<main class="preview-welcome"><div class="eyebrow">WORDLING ISLAND · ADVENTURE PREVIEW</div><h1>A little adventure.<br>A new friend.</h1><div class="welcome-team">${sprite(0)}${sprite(4)}</div><p>3 encounters + a guardian.<br>Every cleared mission brings home a discovery egg.</p><button class="start-button" data-action="guest">Let's play ${icon('arrow')}</button><small>Separate preview progress · saved on this device</small></main>`;}
async function loginForm(form){const button=form.querySelector('button[type="submit"]');if(button.disabled)return;const values=new FormData(form),mode=form.dataset.mode;if(mode==='register'&&values.get('password')!==values.get('confirm')){$('#auth-feedback').textContent='The passwords do not match.';return;}button.disabled=true;$('#auth-feedback').textContent='Connecting to the ranger network…';try{const r=await cloud.auth(mode,values.get('alias'),values.get('password'));state=r.state;alias=r.alias;guest=false;form.reset();if(r.recoveryCode){openModal(modalHeading('Save your recovery code','Keep this code somewhere safe. You need it to reset a forgotten password.')+`<code class="recovery-code">${esc(r.recoveryCode)}</code><p>This code is shown once. Do not share it.</p><button class="next-button" data-action="recovery-done">I saved my code</button>`);}else enterProfile();}catch(e){$('#auth-feedback').textContent=e.message;button.disabled=false;}}
function enterProfile(){if(!state.profile)return showStarter();if(state.mission?.phase==='complete'&&state.mission.egg&&!state.mission.egg.hatched)return renderFinish();if(state.mission&&['question','result'].includes(state.mission.phase))renderHome();else renderHome();}
function showStarter(){view='starter';app.innerHTML=`${header()}<main class="starter-page"><div class="eyebrow">YOUR FIRST FIELD PARTNER</div><h1>Choose your teammate.</h1><p>A free Level 5 partner. It can battle right away!</p><div class="starter-grid">${['leaf','honey','water'].map(id=>{const m=species(id);return `<button class="starter-card" data-action="starter" data-id="${id}">${sprite(indexOf(id))}<h2>${m.name}</h2><span>${m.type}</span><p>${m.description}</p></button>`;}).join('')}</div><p>Your starter counts as owned. Caught totals grow through word battles.</p></main>`;}
function pool(){if(settings.scope==='custom'&&!settings.groupIds.length)return [];return selectPool(data,settings.course,settings.scope==='all'?[]:settings.groupIds);}
function courseName(){if(settings.scope==='all')return settings.course==='ALL'?'CET + FET All words':`${settings.course} All words`;return `${settings.course==='ALL'?'CET + FET':settings.course} · Selected ${settings.groupIds.length} units`;}
function setChoice(action,value,label,active,extra=''){return `<button type="button" class="segment ${active?'active':''}" data-action="${action}" data-value="${value}" aria-pressed="${active}" ${extra}>${label}</button>`;}
function selectedSummary(){if(settings.scope==='all')return settings.course==='ALL'?'All CET Weeks + All FET Lessons':settings.course==='CET'?'All CET Weeks':'All FET Lessons';const selected=data.groups.filter(g=>settings.groupIds.includes(g.id));return selected.slice(0,3).map(g=>`${g.course} ${g.label}`).join(', ')+(selected.length>3?`, total ${selected.length} units`:'')||'No units selected';}
function unitPickerMarkup(){const courses=settings.course==='ALL'?['CET','FET']:[settings.course];return `<div class="course-picker"><div class="unit-actions"><button class="text-button ${settings.scope==='all'?'all-selected':''}" data-action="all-units">${settings.scope==='all'?'✓ ':''}All units</button><button class="text-button" data-action="clear-units">Clear</button><span class="word-count">${pool().length} words</span></div>${courses.map(course=>`<section class="course-unit-panel" aria-label="${course==='CET'?'CET Week selection':'FET Lesson selection'}"><div class="unit-panel-heading"><strong>${course==='CET'?'CET · Choose Weeks':'FET · Choose Lessons'}</strong><span>Multi-select</span><button class="text-button" data-action="course-all" data-course="${course}">Select all ${course}</button></div><div class="visible-unit-grid">${data.groups.filter(g=>g.course===course).map(g=>`<button class="unit-option ${settings.scope==='custom'&&settings.groupIds.includes(g.id)?'selected':''}" data-action="unit" data-value="${g.id}" aria-label="${course} ${g.label}" aria-pressed="${settings.scope==='custom'&&settings.groupIds.includes(g.id)}" title="${esc(g.topic||g.label)}">${g.label}${g.is_review?'<small>Review</small>':''}</button>`).join('')}</div></section>`).join('')}<p class="selection-summary" role="status">${esc(selectedSummary())}</p></div>`;}
function renderHome(openUnits=false){stopBattleAction();stopPark();stopSpeech();view='home';sound.setScene('home');const groups=data.groups.filter(g=>settings.course==='ALL'||g.course===settings.course);const count=pool().length;app.innerHTML=`${header()}<main class="home">${teamOverview()}<div class="home-layout"><section class="home-copy"><div class="eyebrow">HEAR IT. LINK IT. CATCH IT.</div><h1>Ready for an adventure?<br><span style="color:var(--green)">Bring home a friend.</span></h1><p class="intro">Shorter battles. Automatic next words.<br>Clear the guardian to discover your egg.</p><div class="setup">${!storageOK?'<div class="saved-warning">Saving is unavailable in this browser. You can still play. Use a regular browser window to keep your progress.</div>':''}<div class="setup-section"><div class="setup-label"><span class="step-num">1</span>Choose your mode</div><div class="segments">${setChoice('mode','choice',icon('sound')+'Listen & Pick',settings.mode==='choice')}${setChoice('mode','spell','Aa Spell It',settings.mode==='spell')}${setChoice('mode','mixed',icon('sparkle')+'Mixed',settings.mode==='mixed')}</div></div><div class="setup-section"><div class="setup-label"><span class="step-num">2</span>Choose your pace<span class="label-end">Find your pace</span></div><div class="time-line"><div class="segments">${setChoice('timed','false','∞ No timer',!settings.timed)}${setChoice('timed','true',icon('clock')+'Timed',settings.timed)}</div>${settings.timed?`<select class="small-select" id="seconds" aria-label="Seconds per word">${[15,25,40].map(n=>`<option value="${n}" ${settings.seconds===n?'selected':''}>Per word ${n} sec</option>`).join('')}</select>`:''}</div></div><div class="setup-section"><div class="setup-label"><span class="step-num">3</span>Choose your word course<span class="label-end">2026 FALL · G1</span></div><div class="course-segments">${[['ALL','CET + FET'],['CET','CET'],['FET','FET']].map(([value,label])=>`<button class="course-chip ${settings.course===value?'active':''}" data-action="course" data-value="${value}" aria-pressed="${settings.course===value}">${label}</button>`).join('')}</div>${unitPickerMarkup()}</div>${hasActiveMission()?'<button class="secondary-button" data-action="resume-mission" style="width:100%;min-height:44px;justify-content:center;margin-top:14px">Continue current mission</button>':''}<button class="start-button" data-action="start" ${count<1?'disabled':''}><span>${icon('leaf')}${hasActiveMission()?'New mission':'Start mission'}</span>${icon('arrow')}</button><p class="setup-note">${count<1?'Choose at least one unit':`Mission pool: ${count} words · 3 encounters + 1 guardian + discovery egg`}<br>Natural American English · Tap to enable audio</p></div></section><aside class="hero-column" aria-label="Meet the Wordling team"><div class="float-sticker">GEAR UP.<br>LINK UP!<span>READY FOR THE NEXT ENCOUNTER</span></div><div class="hero-scene"><div class="scene-top"><span class="dot"></span>FRONTIER RIDGE · RANGER OUTPOST</div>${sprite(0,'hero-monster')}${sprite(1,'hero-friend')}<span class="word-bubble">hello!</span><img class="hero-player" src="assets/ranger-v3.png" alt="Original field ranger with orange goggles, navy gear, and a laptop scanner"><div class="hero-caption"><span class="caption-icon">${icon('sparkle')}</span><div><strong>Your next teammate is out there.</strong><small>Every word powers your next move.</small></div></div></div><div class="hero-bottom"><span class="hero-feature">${icon('sound')}Listen & learn</span><span class="hero-feature">${icon('book')}Course words</span><span class="hero-feature">${icon('star')}Build your team</span></div></aside></div><footer class="island-line"><span><strong>Small words. Epic adventures.</strong> Every word makes your team stronger.</span><span class="footer-note">KCIS G1 · ${data.summary.unique_word_count} WORDS · MADE FOR LITTLE EXPLORERS</span></footer></main>`;}
function showSoundSettings(){openModal(modalHeading('Audio settings','Set music, effects, and voice levels separately.')+`<div class="audio-settings"><div class="voice-setting"><span class="voice-badge">US</span><div><strong>Jenny · Natural American English</strong><p>Clear American English at a natural pace.</p><small id="voice-status"></small></div><button class="secondary-button" data-action="preview-voice">${icon('sound')}Preview flower</button></div>${[['music','Adventure music','Original adventure score · Soft background mix','musicVolume'],['sfx','Sound effects','Beams, battle moves, letters, and team interactions','sfxVolume']].map(([key,label,note,volume])=>`<div class="audio-control"><div class="audio-control-top"><div><strong>${label}</strong><small>${note}</small></div><button class="audio-toggle ${settings[key]?'on':''}" data-action="toggle-audio" data-setting="${key}" aria-pressed="${settings[key]}" aria-label="${label} toggle">${settings[key]?'On':'Off'}</button></div><label class="volume-line" for="${volume}"><span>Volume</span><input id="${volume}" type="range" min="0" max="100" value="${Math.round(settings[volume]*100)}" data-volume="${volume}" aria-label="${label} volume"><output id="${volume}-value">${Math.round(settings[volume]*100)}%</output></label></div>`).join('')}<div class="audio-control"><label class="volume-line" for="voiceVolume"><span>Voice volume</span><input id="voiceVolume" type="range" min="15" max="100" value="${Math.round(settings.voiceVolume*100)}" data-volume="voiceVolume" aria-label="Voice volume"><output id="voiceVolume-value">${Math.round(settings.voiceVolume*100)}%</output></label></div><p class="audio-hint">Voice comes first: music fades out during speech and returns softly afterward. Effects also become quieter. Audio starts after your first tap; leaving the tab pauses it.</p></div>`);updateVoiceStatus();speaker.ready.then(()=>updateVoiceStatus());}
async function startGame(restart=false){
 if(!pool().length)return;
 if(hasActiveMission()&&!restart){openModal(modalHeading('Start a new mission?','Your current adventure is not finished. Your monsters and earned XP will stay saved.')+`<p>New words: <strong>${esc(selectedSummary())}</strong></p><div class="finish-actions"><button class="secondary-button" data-action="resume-mission">Continue current mission</button><button class="next-button" data-action="restart-mission">Start new mission${icon('arrow')}</button></div>`);return;}
 stopBattleAction();stopSpeech();await act({type:restart?'restart':'start',settings});await closeMenu();sfx('start');paused=false;intent='attack';window.scrollTo(0,0);syncRound(true);
}
function syncRound(newWord=false){const m=state.mission;if(!m)return renderHome();if(['complete','rescued'].includes(m.phase))return renderFinish();const q=m.question;const same=round?.id===q.id;round={id:q.id,card:data.cards.find(c=>c.id===q.cardId),mode:q.mode,phase:m.phase,options:q.options,letters:q.letters,selected:same?round.selected:[],message:'',assisted:same?round.assisted:false,result:m.result};if(!same||newWord){remainingMs=m.settings.seconds*1000;waitingForAudio=m.phase==='question';}intent='attack';autoHeld=false;lastTick=Date.now();renderBattle();clearInterval(timerId);timerId=setInterval(tick,120);if(m.phase==='question'&&(!same||newWord)&&!paused)speak(round.card.english,{first:true});else if(m.phase==='result'&&!paused)startReview();}
function enemySpecies(){return species(state.mission.enemy.instance.speciesId);}
function currentMonster(){return indexOf(state.mission.enemy.instance.speciesId);}
function hpBar(value,max,label,cls=''){return `<div class="hp-line"><span>${label}</span><div class="hp-track ${cls}" role="progressbar" aria-label="${label}" aria-valuemin="0" aria-valuemax="${max}" aria-valuenow="${value}"><div class="hp-fill" style="width:${Math.max(0,value/max*100)}%"></div></div><small>${value}/${max}</small></div>`;}
function renderBattle(){
 stopPark();view='game';const m=state.mission,p=state.profile,e=enemySpecies(),ally=p.inventory.find(x=>x.id===m.active),a=species(ally.speciesId),stats=monsterStats(ally,MONSTERS),v=m.vitals[ally.id];sound.setScene(m.enemy.boss?'boss':'field');
 app.innerHTML=`${header(true)}<main class="game-page"><div class="adventure-toolbar"><strong>${m.enemy.boss?'Guardian · Find your egg!':'Frontier Ridge'}</strong><div class="journey-path" aria-label="Encounter ${m.stage+1} of ${MISSION_STAGES}">${Array.from({length:MISSION_STAGES},(_,i)=>`<span class="path-node ${i<m.stage?'complete':i===m.stage?'current':''}">${i<m.stage?'✓':i===MISSION_STAGES-1?'★':i+1}</span>`).join('')}</div></div><section class="arena rpg-arena ${m.enemy.boss?'boss':''}" aria-label="Monster battle arena"><div class="monster-status"><div class="monster-name"><strong>${e.name}</strong>${badge(e)}</div><small>${m.enemy.boss?'GUARDIAN · ':''}${e.type} · Lv.${m.enemy.instance.level}</small>${hpBar(m.enemy.hp,m.enemy.maxHp,'HP')}</div><div class="encounter-bubble" id="encounter-bubble">${m.enemy.boss?'The guardian is protecting a discovery egg.':canCatch(m)&&m.enemy.hp?'Catch is ready!':'Your words power your next move.'}</div><div class="enemy-wrap ${m.enemy.boss?'boss-enemy':''} ${m.result?.captured?'captured':''}" id="enemy-wrap"><div class="enemy-shadow"></div>${sprite(currentMonster(),'enemy')}<span class="enemy-word ${m.phase==='question'?'':'revealed'}" id="enemy-word">${m.phase==='question'?'?':esc(round.card.english)}</span></div><div class="ally-wrap" id="ally-wrap">${sprite(indexOf(a.id),'ally-monster')}</div><div class="hero-actor rpg-ranger" id="hero-actor"><img class="arena-player" src="assets/ranger-v3.png" alt="Ranger"><div class="hero-action-sprite" aria-hidden="true"></div></div><div class="action-caption" role="status" aria-live="polite"></div><div class="player-status rpg-player-status"><strong>${a.name}<small>Lv.${ally.level}</small></strong>${hpBar(v.hp,stats.hp,'HP')}${hpBar(v.mp,stats.mp,'MP','mp-track')}</div><div class="timer-badge" id="timer-badge">${icon(m.settings.timed?'clock':'leaf')}<span id="time-left">${m.settings.timed?Math.ceil(remainingMs/1000)+'s':'Take your time'}</span></div></section><section class="computer-shell"><div class="move-picker" aria-label="Choose a battle action">${[['attack','Attack','+4 MP'],['special',a.specialMove,`${specialCost(a)} MP`],['catch','Catch',canCatch(m)?'Ready!':'Weaken first']].map(([id,label,note])=>`<button data-action="intent" data-value="${id}" class="move-button ${intent===id?'selected':''}" aria-pressed="${intent===id}" ${m.phase!=='question'||id==='catch'&&!canCatch(m)||id==='special'&&v.mp<specialCost(a)?'disabled':''}><strong>${label}</strong><small>${note}</small></button>`).join('')}</div><div class="computer-screen" id="computer-screen">${m.phase==='question'?questionMarkup():resultMarkup()}</div></section><div class="battle-footer"><span>${m.captures.length} caught · ${m.score} pts</span><button data-action="team-menu">${icon('back')} Switch teammate</button></div></main>${paused?pauseMarkup():''}`;
}
function questionMarkup(){return `<div class="question-top"><div class="question-label"><button class="audio-button" data-action="replay" aria-label="Listen again">${icon('sound')}</button><div><strong>${round.mode==='choice'?'Listen. Pick the word!':'Listen. Build the word!'}</strong><small>${round.mode==='choice'?'Your answer powers the move.':'Tap letters in order.'}</small></div></div><button class="help-button" data-action="hint">Hint</button></div>${round.mode==='choice'?`<div class="choice-grid">${round.options.map((word,i)=>`<button class="answer-choice" data-action="answer" data-word="${esc(word)}"><span class="key">${i+1}</span>${esc(word)}</button>`).join('')}</div>`:spellMarkup()}<div class="feedback" id="feedback" role="status">${esc(round.message)}</div>`;}
function spellMarkup(){return `<div class="spell-slots" aria-label="Your letter order">${[...round.card.english].map((_,i)=>round.selected[i]!==undefined?`<button class="letter-slot filled" data-action="unletter" data-index="${i}" aria-label="Remove letter in slot ${i+1}">${esc(round.letters.find(t=>t.id===round.selected[i]).letter)}</button>`:`<span class="letter-slot" aria-label="Empty slot ${i+1}"></span>`).join('')}</div><div class="letter-bank">${round.letters.map(t=>`<button class="letter-tile" data-action="letter" data-id="${t.id}" aria-label="Choose letter ${t.letter}" ${round.selected.includes(t.id)?'disabled':''}>${esc(t.letter)}</button>`).join('')}</div><div class="spell-tools"><button data-action="backspace">Undo</button><button data-action="clear-letters">Clear letters</button></div>`;}
function updateQuestion(){if($('#computer-screen'))$('#computer-screen').innerHTML=questionMarkup();if(speaking)$('.audio-button')?.classList.add('speaking');}
function resultMarkup(){const r=state.mission.result;return `<div class="result-row ${r.correct?'correct-result':'wrong-result'}"><div class="result-copy"><div class="eyebrow">${r.captured?'NEW TEAMMATE!':r.correct?'GREAT WORD LINK!':'LET’S LEARN THIS ONE'}</div><div class="result-word">${esc(round.card.english)}<small>${esc(round.card.meaning_zh)}</small></div><p>${r.captured?`You caught ${enemySpecies().name}!`:r.correct?r.finishedEncounter?'Well done! On to the next encounter.':`Direct hit! −${r.damage} HP`:'Listen to the answer. You can do it!'}</p></div><div class="review-controls"><button class="audio-button" data-action="review-replay" aria-label="Hear the answer">${icon('sound')}</button><button class="help-button hold-button" data-action="hold-next">${autoHeld?'Continue automatically':'Wait'}</button>${r.captured?'<button class="help-button" data-action="recruit">Join team</button>':''}<button class="next-button" data-action="next">${r.rescued?'Back to base':state.mission.enemy.boss&&r.finishedEncounter?'Find egg':'Continue'}${icon('arrow')}</button></div><div class="auto-status" id="auto-status" role="status">Listening, then continuing automatically…</div></div>`;}
async function submitAnswer(answer,{timeout=false}={}){if(actionBusy||networkBusy||view!=='game'||round?.phase!=='question'||paused||modal.open)return;const qid=round.id,assisted=round.assisted;stopSpeech();waitingForAudio=false;lockBattleControls(true);try{await act({type:'answer',questionId:qid,intent,answer,hint:assisted,timeout});round.phase='result';round.result=state.mission.result;renderBattle();await runBattleAction(round.result.correct?(round.result.captured?'capture':round.result.intent==='catch'?'miss':'hit'):'wrong',currentMonster());}catch(e){toast(e.message);round.selected=[];updateQuestion();lastTick=Date.now();if(remainingMs===0)pause();if(e.status===409)syncRound(true);}finally{lockBattleControls(false);}}
function lockBattleControls(value){$('#computer-screen')?.setAttribute('aria-busy',String(value));document.querySelectorAll('#computer-screen button,.move-picker button,.battle-team button').forEach(b=>{if(value){if(!b.disabled){b.dataset.actionLocked='true';b.disabled=true;}}else if(b.dataset.actionLocked){delete b.dataset.actionLocked;b.disabled=false;}});}
function stopBattleAction(){autoAdvance.cancel();if(battleAction){battleAction.cancel();battleAction=null;}actionBusy=false;lockBattleControls(false);}
async function runBattleAction(kind,index){stopBattleAction();stopSpeech();actionBusy=true;lockBattleControls(true);const action=battleAction=new BattleAction($('.arena'),sound,speaker),r=state.mission.result;try{await action.play(kind,index,state.mission.enemy.boss&&r.finishedEncounter,{damage:r.damage,counterDamage:r.counterDamage,special:r.intent==='special',type:species(state.profile.inventory.find(m=>m.id===state.mission.active).speciesId).type,move:r.intent==='special'?species(state.profile.inventory.find(m=>m.id===state.mission.active).speciesId).specialMove:'ATTACK!',enemyMove:r.enemySpecial?enemySpecies().specialMove:enemySpecies().type+' STRIKE',defeated:r.finishedEncounter&&!r.captured});}catch{toast('Ready for your next word.');}if(battleAction!==action)return;action.clean();battleAction=null;actionBusy=false;lockBattleControls(false);lastTick=Date.now();if(view==='game'&&!paused)startReview();}
function startReview(){if(view!=='game'||round?.phase!=='result'||paused||modal.open)return;const id=round.id,r=state.mission.result;autoAdvance.reset(id,r.captured?4200:r.correct?1600:3600);autoAdvance.hold(autoHeld);speak(round.card.english,{onDone:()=>{if(round?.id===id&&view==='game'&&!paused)autoAdvance.arm(id);}});}
function updateAutoStatus(){const el=$('#auto-status');if(!el)return;el.textContent=autoHeld?'Take your time. Tap Continue when ready.':!autoAdvance.ready?'Listening, then continuing automatically…':`Next ${state.mission.result.finishedEncounter?'encounter':'word'} in ${Math.max(1,Math.ceil(autoAdvance.remaining/1000))}…`;}
function showTeamMenu(){openModal(modalHeading('Choose your teammate')+`<div class="team-choices">${state.profile.team.map(id=>{const inst=state.profile.inventory.find(m=>m.id===id),s=species(inst.speciesId);return `<button class="secondary-button" data-action="switch" data-id="${id}" ${round.phase!=='question'||!state.mission.vitals[id]?.hp?'disabled':''}>${sprite(indexOf(s.id))}${s.name} · ${state.mission.vitals[id]?.hp||0} HP</button>`;}).join('')}</div>`);}
async function nextRound(){if(actionBusy||networkBusy||paused)return;stopBattleAction();stopSpeech();await act({type:'next'});syncRound(true);}
function chooseLetter(id){if(actionBusy||networkBusy||paused||round?.phase!=='question'||round.mode!=='spell'||round.selected.includes(id))return;sfx('letter');round.selected.push(id);round.message='';updateQuestion();if(round.selected.length===round.letters.length)submitAnswer(round.selected.map(id=>round.letters.find(t=>t.id===id).letter).join(''));}
function tick(){const now=Date.now(),dt=Math.min(500,now-lastTick);lastTick=now;if(view!=='game'||paused||actionBusy||networkBusy||modal.open||document.hidden)return;if(round?.phase==='result'){const due=autoAdvance.tick(dt,{active:!speaking});updateAutoStatus();if(due)nextRound().catch(e=>{autoHeld=true;toast(e.message);});return;}if(round?.phase!=='question'||waitingForAudio||!state.mission.settings.timed)return;remainingMs=Math.max(0,remainingMs-dt);if($('#time-left'))$('#time-left').textContent=Math.ceil(remainingMs/1000)+'s';$('#timer-badge')?.classList.toggle('urgent',remainingMs<6000);if(!remainingMs)submitAnswer('',{timeout:true});}
function pauseMarkup(){return `<div class="pause-cover"><h2>Take a break.</h2><p>Your adventure is saved.</p><button class="next-button" data-action="resume">${icon('arrow')} Keep playing</button><div class="pause-links"><button class="secondary-button" data-action="sound-settings">${icon('music')} Audio</button><button class="secondary-button" data-action="park">${icon('park')} Team Park</button><button class="secondary-button" data-action="warehouse">${icon('book')} Collection</button><button class="secondary-button" data-action="confirm-home">Back to base</button></div></div>`;}
function pause(){if(view!=='game'||paused)return;stopBattleAction();stopSpeech();paused=true;app.insertAdjacentHTML('beforeend',pauseMarkup());}
function resume(){paused=false;$('.pause-cover')?.remove();lastTick=Date.now();if(round.phase==='result')startReview();else if(waitingForAudio)speak(round.card.english,{first:true});}
function confirmHome(){if(view!=='game')return renderHome();pause();openModal(modalHeading('Return to base?','Caught teammates and earned XP stay saved. This mission will end.')+`<div class="finish-actions"><button class="secondary-button" data-action="close-modal">Keep playing</button><button class="next-button" data-action="leave-game">Return to base</button></div>`);}
function renderFinish(){stopBattleAction();stopPark();stopSpeech();clearInterval(timerId);view='finish';const m=state.mission,cleared=m.phase==='complete';sound.setScene('park');if(cleared&&m.egg&&!m.egg.hatched){renderEgg();return;}app.innerHTML=`${header()}<main class="finish-page"><div class="eyebrow">${cleared?'MISSION COMPLETE':'YOUR TEAM IS SAFE'}</div><h1>${cleared?'A new friend. A great adventure!':'Rest up, ranger.'}</h1><div class="finish-monsters">${m.captures.map(id=>sprite(indexOf(state.profile.inventory.find(x=>x.id===id).speciesId))).join('')||sprite(currentMonster())}</div><p>${cleared?'Your discovery friend is waiting in Team Park.':'Your teammates and XP are safe.'}</p><div class="records-summary"><div class="record-number"><strong>${m.score}</strong>Points</div><div class="record-number"><strong>${m.captures.length}</strong>New friends</div><div class="record-number"><strong>${Math.round(m.correct/Math.max(1,m.attempts)*100)}%</strong>Accuracy</div></div><div class="finish-actions"><button class="next-button" data-action="park">Meet your friend ${icon('arrow')}</button><button class="secondary-button" data-action="home">Back to base</button></div></main>`;}
function renderEgg(){document.body.dataset.screen='egg';app.innerHTML=`<main class="egg-page"><div class="eyebrow">GUARDIAN CLEARED · DISCOVERY REWARD</div><h1>You found an egg!</h1><p>A friend from this adventure is inside.</p><div class="egg-stage" id="egg-stage"><div class="egg-halo"></div><button class="egg-button" data-action="hatch" aria-label="Hatch your discovery egg">${item('egg','discovery-egg')}</button></div><button class="next-button" data-action="hatch">Tap to hatch ${icon('sparkle')}</button><small>One discovery egg. Every cleared adventure.</small></main>`;}
async function hatchEgg(){if(hatchBusy||state.mission?.egg?.hatched)return;hatchBusy=true;stopSpeech();const missionId=state.mission.id;try{await act({type:'hatch'});const friend=state.profile.inventory.find(m=>m.id===state.mission.egg.monsterId);document.querySelectorAll('[data-action="hatch"]').forEach(b=>b.disabled=true);const stage=$('#egg-stage');stage.classList.add('hatching');sfx('crack');await new Promise(r=>setTimeout(r,700));if(state.mission?.id!==missionId)return;stage.querySelector('.discovery-egg').src='preview/assets/egg-cracked.png';sfx('crack');await new Promise(r=>setTimeout(r,650));if(state.mission?.id!==missionId)return;stage.innerHTML=`<div class="egg-halo"></div>${item('egg-shell','egg-shell')}${sprite(indexOf(friend.speciesId),'hatched-friend')}`;stage.classList.add('hatched');sound.cry(indexOf(friend.speciesId));sfx('success');$('.egg-page h1').textContent=species(friend.speciesId).name+'!';$('.egg-page p').textContent='Your new teammate came from this adventure.';const b=$('.egg-page>.next-button');b.disabled=false;b.dataset.action='egg-done';b.innerHTML='Bring my friend home '+icon('arrow');}finally{hatchBusy=false;}}
function statsMarkup(inst){const stats=monsterStats(inst,MONSTERS);return `<dl class="stat-grid">${STAT_KEYS.map(k=>`<div><dt>${k.toUpperCase()}</dt><dd>${stats[k]}<small>IV ${inst.iv[k]}/31</small></dd></div>`).join('')}</dl><small>Quality ${quality(inst)}% · Lv.${inst.level} · XP ${inst.xp}/${inst.level*35} · Individual values affect stats</small>`;}
function showWarehouse(){if(!state.profile)return toast('Choose your first teammate.');const p=state.profile,filtered=p.inventory.filter(x=>warehouseFilter==='All'||species(x.speciesId).rarity===warehouseFilter).toSorted((a,b)=>RARITIES.indexOf(species(b.speciesId).rarity)-RARITIES.indexOf(species(a.speciesId).rarity)||b.level-a.level),pages=Math.max(1,Math.ceil(filtered.length/12));warehousePage=Math.min(warehousePage,pages-1);const active=state.mission&&['question','result'].includes(state.mission.phase);openModal(modalHeading('Monster warehouse',`${p.inventory.length} teammates · Team ${p.team.length}/3 · Select up to 3 for battle`)+`<div class="warehouse-toolbar"><select id="rarity-filter" aria-label="Filter by rarity">${['All',...RARITIES].map(r=>`<option ${warehouseFilter===r?'selected':''}>${r}</option>`).join('')}</select><button class="secondary-button" data-action="collection">100-species field guide</button></div>${active?'<p>Return to base to reorganize your team. Newly caught teammates can join immediately from the battle result.</p>':''}<div class="warehouse-grid">${filtered.slice(warehousePage*12,warehousePage*12+12).map(inst=>{const m=species(inst.speciesId),on=p.team.includes(inst.id);return `<article class="warehouse-card ${on?'on-team':''}"><div class="warehouse-card-top">${badge(m)}<small>#${String(m.dex).padStart(3,'0')}</small></div>${sprite(indexOf(m.id))}<h3>${esc(m.name)} <small>${m.type}</small></h3>${statsMarkup(inst)}<div class="ability"><strong>${esc(m.ability.name)}</strong><p>${esc(m.ability.description)}</p><small>Special: ${esc(m.specialMove)} · ${specialCost(m)} MP</small></div><button class="secondary-button" data-action="team-toggle" data-id="${inst.id}" ${active||on&&p.team.length===1||!on&&p.team.length===3?'disabled':''}>${on?'✓ On team · Remove':'Add to battle team'}</button><small class="caught-date">${inst.origin==='starter'?'Starter gift':inst.origin==='legacy'?'Previous local collection':'Caught '+new Date(inst.caughtAt).toLocaleDateString('en-US')}</small></article>`;}).join('')||'<p>No teammates match this rarity yet.</p>'}</div><div class="pagination"><button data-action="warehouse-prev" ${warehousePage===0?'disabled':''}>Previous</button><span>${warehousePage+1} / ${pages}</span><button data-action="warehouse-next" ${warehousePage>=pages-1?'disabled':''}>Next</button></div>`);}
function showCollection(){const p=state.profile;if(!p)return toast('Choose your starter first.');const owned=new Set(p.inventory.map(x=>x.speciesId)),odds=encounterOdds(p.adventures,settings.mode);openModal(modalHeading('100-species field guide',`${owned.size}/100 species owned · ${p.adventures} missions cleared`)+`<div class="rarity-guide">${RARITIES.map(r=>`<div>${badge({rarity:r})}<span>${p.adventures<UNLOCKS[r]?'Unlock: '+UNLOCKS[r]+' cleared missions':(odds[r]*100).toFixed(2)+'% encounter chance'}</span><small>Catch: ${Math.round(CATCH_RATES[r]*100)}% per correct attempt</small></div>`).join('')}</div><p>Spell It gives Rare, Epic, and Legendary encounter weights a 15% boost. Unlocks and catch rates stay the same. A monster can escape after 3 failed catches.</p><div class="collection-grid full-dex">${MONSTERS.map((m,i)=>`<article class="collection-card ${owned.has(m.id)?'':'locked'}"><span class="caught-mark">${owned.has(m.id)?'✓ Owned':'Not caught'}</span>${sprite(i)}<small>#${String(m.dex).padStart(3,'0')} · ${m.type}</small><h3>${m.name}</h3>${badge(m)}<p>${m.description}</p></article>`).join('')}</div>`);}
async function showLeaderboard(){openModal(modalHeading('Ranger leaderboard','Loading the ranger network…')+'<p role="status">Fetching real player collections…</p>');try{const result=await cloud.leaderboard();if(!modal.open)return;modal.innerHTML=modalHeading('Ranger leaderboard',`${result.players} registered players · Top 100 collections`)+`<p>Ranked by rarity points, then unique species and caught totals. Starter gifts do not add caught totals or rarity points.</p><p class="ranking-key">Common 1 · Uncommon 3 · Rare 10 · Epic 35 · Legendary 150 points</p><div class="leaderboard-scroll"><table class="leaderboard"><thead><tr><th>Rank</th><th>Player</th><th>Caught</th><th>Species</th><th>Common</th><th>Uncommon</th><th>Rare</th><th>Epic</th><th>Legendary</th><th>Points</th></tr></thead><tbody>${result.rows.map((r,i)=>`<tr class="${r.alias===alias?'you':''}"><td>${i+1}</td><th scope="row">${esc(r.alias)}</th><td>${r.caught}</td><td>${r.unique_species}/100</td>${RARITIES.map(k=>`<td>${r.rarity_counts[k]||0}</td>`).join('')}<td>${r.rarity_points}</td></tr>`).join('')||'<tr><td colspan="10">No players yet. Create your ranger code to join!</td></tr>'}</tbody></table></div><p>${guest?'Guest collections stay on this device and are not ranked.':'Your collection updates after each saved move.'}</p><button class="secondary-button" data-action="leaderboard">Refresh</button>`;}catch(e){modal.innerHTML=modalHeading('Ranger leaderboard')+`<p>${esc(e.message)}</p><button class="secondary-button" data-action="leaderboard">Try again</button>`;}}
function parkDetail(index){const m=MONSTERS[index],count=state.profile.inventory.filter(x=>x.speciesId===m.id).length;return `<div><strong>${m.name}</strong><small>${m.type} · ${count} owned · Choose something to do</small></div>`;}
function showPark(refresh=false){if(!state.profile)return toast('Choose your starter first.');if(view!=='park'){parkReturnView=view;parkWasPaused=paused;}else if(!refresh)return;stopBattleAction();if(view==='game')paused=true;stopSpeech();stopPark();view='park';sound.setScene('park');const owned=MONSTERS.map((m,index)=>({...m,index})).filter(m=>state.profile.inventory.some(x=>x.speciesId===m.id)),pages=Math.max(1,Math.ceil(owned.length/12));parkPage=Math.min(parkPage,pages-1);const residents=owned.slice(parkPage*12,parkPage*12+12);if(!residents.some(m=>m.id===selectedParkId))selectedParkId=residents[0]?.id;app.innerHTML=`${header()}<main class="park-page"><div class="park-heading"><h1>Life in Team Park</h1><span>${owned.length} species · ${parkPage+1}/${pages}</span></div><section class="park-world" id="park-world" aria-label="Park with your monster friends"><div class="park-sign">TEAM PARK<small>REST. PLAY. GROW.</small></div><div class="park-prop" id="park-prop"></div>${residents.map(m=>`<button class="park-creature ${m.id===selectedParkId?'chosen':''}" data-action="select-monster" data-park-id="${m.id}" aria-label="Select ${m.name}" aria-pressed="${m.id===selectedParkId}"><span class="park-shadow"></span><span class="park-face">${sprite(m.index,'park-sprite')}</span><span class="park-monster-name">${m.name}</span><span class="park-heart">${item('heart')}</span><span class="pet-hand">${item('hand')}</span></button>`).join('')}<div class="park-activity" id="park-activity" role="status">Tap a friend. Choose an activity.</div></section><section class="park-panel"><div class="park-detail" id="park-detail">${selectedParkId?parkDetail(indexOf(selectedParkId)):''}</div><div class="care-actions"><button data-action="park-feed">${item('snack')}<strong>Snack</strong><small>Eat & enjoy</small></button><button data-action="park-pet">${item('hand')}<strong>Pet</strong><small>A little love</small></button><button data-action="park-train">${item('dummy')}<strong>Train</strong><small>Show your move</small></button></div></section>${pages>1?`<div class="pagination"><button data-action="park-prev" ${parkPage===0?'disabled':''}>Previous</button><button data-action="park-next" ${parkPage>=pages-1?'disabled':''}>Next</button></div>`:''}</main>`;park=new MonsterPark($('#park-world'),residents,{onActivity:(message,index,kind)=>{const el=$('#park-activity');if(el)el.textContent=message;if(kind==='eat')sfx('feed');else if(kind==='pet')sound.cry(index);else if(kind==='strike')sound.impact(MONSTERS[index].type,true);}});}
function selectParkFriend(id){if(park?.busy)return;selectedParkId=id;document.querySelectorAll('.park-creature').forEach(b=>{b.classList.toggle('chosen',b.dataset.parkId===id);b.setAttribute('aria-pressed',String(b.dataset.parkId===id));});$('#park-detail').innerHTML=parkDetail(indexOf(id));}
function care(kind){if(!park||!selectedParkId||park.busy)return;const task=park.activity(selectedParkId,kind);$('.care-actions').setAttribute('aria-busy','true');document.querySelectorAll('.care-actions button').forEach(b=>b.disabled=true);task.finally(()=>{if(view==='park'){$('.care-actions')?.setAttribute('aria-busy','false');document.querySelectorAll('.care-actions button').forEach(b=>b.disabled=false);}});}
function backFromPark(){stopPark();stopSpeech();if(parkReturnView==='game'&&state.mission){paused=parkWasPaused;renderBattle();lastTick=Date.now();if(waitingForAudio&&!paused&&round.phase==='question')speak(round.card.english,{first:true});else if(!paused&&round.phase==='result')startReview();}else if(parkReturnView==='finish'&&state.mission)renderFinish();else renderHome();}
function showRecords(){const p=state.profile,words=Object.keys(p.words).sort();openModal(modalHeading('Mission records',guest?'Saved on this device':'Synced to your player code')+`<div class="records-summary"><div class="record-number"><strong>${words.filter(w=>p.words[w].correct>0).length}</strong>Words practiced</div><div class="record-number"><strong>${p.adventures}</strong>Missions cleared</div><div class="record-number"><strong>${p.bestScore}</strong>Best score</div></div><div class="word-records">${words.map(w=>`<span>${esc(w)} <small>✓ ${p.words[w].correct}/${p.words[w].attempts}</small></span>`).join('')||'<p>Your first word starts here.</p>'}</div>`);}
function help(){openModal(modalHeading('Your little adventure')+`<div class="help-content"><h3>Listen. Pick. Battle!</h3><p>Choose Attack, Special, or Catch. Answer a word to power the move. Basic attacks restore MP. Special moves use MP and hit harder.</p><h3>Keep going automatically</h3><p>The game reads the answer, then continues automatically. Tap Wait or Pause for more time. Wrong answers get a longer review.</p><h3>Find your discovery egg</h3><p>Face 3 ordinary encounters and a guardian. Every cleared mission gives an egg containing one species you met. Catching weakened monsters is an extra reward.</p><h3>Care for your friends</h3><p>In Team Park, choose a friend, then Snack, Pet, or Train. Watch them eat, enjoy a pet, and practice their move.</p><p>This preview uses a separate save on this device.</p></div>`);}
function showAccount(){openModal(modalHeading('Adventure preview','Progress is saved separately on this device.')+`<div class="finish-actions"><button class="secondary-button" data-action="records">Word records</button><button class="secondary-button" data-action="collection">Field guide</button><button class="secondary-button" data-action="help">How to play</button><button class="secondary-button" data-action="home">Back to base</button></div>`);}
function recover(){openModal(modalHeading('Recover your ranger account','Use the recovery code saved when you created your player.')+`<form id="recover-form"><label>Player code<input name="alias" required autocapitalize="none" autocomplete="username"></label><label>Recovery code<input name="recovery" required autocapitalize="none" spellcheck="false" minlength="32" maxlength="40"></label><label>New password<input type="password" name="password" required minlength="8" maxlength="64" autocomplete="new-password"></label><p id="recover-feedback" role="status"></p><button class="next-button">Reset password</button></form>`);}
async function dispatch(action,target){if((actionBusy||networkBusy)&&['answer','letter','unletter','backspace','clear-letters','replay','hint','next','intent','switch','recruit','restart-mission','start','resume-mission'].includes(action))return;switch(action){
 case 'auth-mode':renderAuth(target.dataset.mode);break;
 case 'guest':{guest=true;alias='';state=read('wordling-preview-save-v3',null)||{profile:null,mission:null};save();enterProfile();break;}
 case 'starter':await act({type:'starter',speciesId:target.dataset.id});renderHome();break;
 case 'recovery-done':modal.close();enterProfile();break;
 case 'recover':recover();break;
 case 'mode':settings.mode=target.dataset.value;save();renderHome();break;
 case 'timed':settings.timed=target.dataset.value==='true';save();renderHome();break;
 case 'course':settings.course=target.dataset.value;settings.scope='all';settings.groupIds=[];save();renderHome();break;
 case 'unit':{const id=target.dataset.value;if(settings.scope==='all'){settings.groupIds=[];settings.scope='custom';}settings.groupIds=settings.groupIds.includes(id)?settings.groupIds.filter(n=>n!==id):[...settings.groupIds,id];save();renderHome();break;}
 case 'course-all':settings.scope='custom';settings.groupIds=data.groups.filter(g=>g.course===target.dataset.course).map(g=>g.id);save();renderHome();break;
 case 'all-units':settings.scope='all';settings.groupIds=[];save();renderHome();break;
 case 'clear-units':settings.scope='custom';settings.groupIds=[];save();renderHome();break;
 case 'start':await startGame();break;
 case 'resume-mission':await closeMenu();paused=false;syncRound(true);break;
 case 'restart-mission':target.disabled=true;try{await startGame(true);}finally{if(target.isConnected)target.disabled=false;}break;
 case 'answer':await submitAnswer(target.dataset.word);break;
 case 'letter':chooseLetter(Number(target.dataset.id));break;
 case 'unletter':if(round?.phase==='question'&&!paused){round.selected.splice(Number(target.dataset.index),1);updateQuestion();}break;
 case 'backspace':if(round?.phase==='question'&&!paused){round.selected.pop();updateQuestion();}break;
 case 'clear-letters':if(round?.phase==='question'&&!paused){round.selected=[];updateQuestion();}break;
 case 'intent':intent=target.dataset.value;document.querySelectorAll('.move-button').forEach(b=>{b.classList.toggle('selected',b.dataset.value===intent);b.setAttribute('aria-pressed',b.dataset.value===intent);});break;
 case 'switch':await act({type:'switch',id:target.dataset.id});modalPaused=false;modal.close();paused=false;renderBattle();if(waitingForAudio)speak(round.card.english,{first:true});break;
 case 'recruit':await act({type:'recruit',id:state.mission.captures.at(-1)});renderBattle();startReview();toast('Your new teammate is ready!');break;
 case 'replay':if(!paused)speak(round.card.english,{first:waitingForAudio});break;
 case 'speak-word':speak(target.dataset.word);break;
 case 'hint':if(round?.phase==='question'&&!paused){round.assisted=true;round.message=`Hint: ${round.card.english} — ${round.card.meaning_zh}`;$('#enemy-word').textContent=round.card.english;$('#enemy-word').classList.add('revealed');updateQuestion();}break;
 case 'next':autoAdvance.cancel();await nextRound();break;
 case 'hold-next':autoHeld=!autoHeld;autoAdvance.hold(autoHeld);target.textContent=autoHeld?'Continue automatically':'Wait';updateAutoStatus();break;
 case 'review-replay':startReview();break;
 case 'team-menu':showTeamMenu();break;
 case 'hatch':await hatchEgg();break;
 case 'egg-done':selectedParkId=state.mission.egg.speciesId;renderFinish();break;
 case 'select-monster':selectParkFriend(target.dataset.parkId);break;
 case 'park-pet':care('pet');break;
 case 'park-train':care('train');break;
 case 'pause':pause();break;
 case 'resume':resume();break;
 case 'home':if(modal.open){modalPaused=false;modal.close();}if(!state.profile){renderAuth();break;}if(view==='game')confirmHome();else if(view==='park'&&parkReturnView==='game'){backFromPark();confirmHome();}else{stopBattleAction();stopSpeech();renderHome();}break;
 case 'confirm-home':confirmHome();break;
 case 'leave-game':await act({type:'leave'});modalPaused=false;modal.close();clearInterval(timerId);stopSpeech();paused=false;round=null;renderHome();break;
 case 'park':showPark();break;
 case 'park-back':backFromPark();break;
 case 'park-prev':parkPage--;showPark(true);break;
 case 'park-next':parkPage++;showPark(true);break;
 case 'park-gather':park?.gather();sfx('start');$('#park-activity').textContent='Rally up!';break;
 case 'park-feed':care('feed');break;
 case 'pet-monster':park?.pet(target.dataset.parkId);break;
 case 'warehouse':showWarehouse();break;
 case 'warehouse-prev':warehousePage--;showWarehouse();break;
 case 'warehouse-next':warehousePage++;showWarehouse();break;
 case 'team-toggle':{const p=state.profile,ids=p.team.includes(target.dataset.id)?p.team.filter(id=>id!==target.dataset.id):[...p.team,target.dataset.id];await act({type:'team',ids});showWarehouse();break;}
 case 'collection':showCollection();break;
 case 'leaderboard':await showLeaderboard();break;
 case 'records':showRecords();break;
 case 'account':showAccount();break;
 case 'logout':stopBattleAction();stopPark();stopSpeech();clearInterval(timerId);if(!guest)await cloud.logout();guest=false;state={profile:null,mission:null};alias='';modalPaused=false;modal.close();renderAuth();break;
 case 'sound-settings':showSoundSettings();break;
 case 'preview-voice':speak('flower');break;
 case 'toggle-audio':{const key=target.dataset.setting;settings[key]=!settings[key];sound.activate();sound.update();save();target.classList.toggle('on',settings[key]);target.setAttribute('aria-pressed',settings[key]);target.textContent=settings[key]?'On':'Off';break;}
 case 'help':help();break;
 case 'close-modal':stopSpeech();modal.close();break;
}}
document.addEventListener('pointerdown',()=>sound.activate(),{once:true});
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(!target||target.disabled||modal.open&&!modal.contains(target))return;dispatch(target.dataset.action,target).catch(e=>toast(e.message));});
document.addEventListener('submit',e=>{if(e.target.id==='account-form'){e.preventDefault();loginForm(e.target);}if(e.target.id==='recover-form'){e.preventDefault();const f=e.target,v=new FormData(f),b=f.querySelector('button');b.disabled=true;cloud.request('recover',{alias:v.get('alias'),password:v.get('password'),recoveryCode:v.get('recovery')}).then(r=>{modal.innerHTML=modalHeading('Password reset','Save this new recovery code. The old code no longer works.')+`<code class="recovery-code">${r.recoveryCode}</code><button class="next-button" data-action="close-modal">Saved · Sign in</button>`;}).catch(e=>{$('#recover-feedback').textContent=e.message;b.disabled=false;});}});
document.addEventListener('input',e=>{const key=e.target.dataset.volume;if(!key)return;settings[key]=Number(e.target.value)/100;sound.update();save();$('#'+key+'-value').textContent=e.target.value+'%';});
document.addEventListener('change',e=>{if(e.target.id==='seconds'){settings.seconds=Number(e.target.value);save();}if(e.target.id==='rarity-filter'){warehouseFilter=e.target.value;warehousePage=0;showWarehouse();}});
modal.addEventListener('close',()=>{stopSpeech();if(modalPaused&&view==='game'){paused=false;lastTick=Date.now();if(waitingForAudio&&round?.phase==='question')speak(round.card.english,{first:true});else if(round?.phase==='result')startReview();}modalPaused=false;});
document.addEventListener('keydown',e=>{if(view!=='game'||modal.open||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='Escape'){e.preventDefault();paused?resume():pause();return;}if(paused||actionBusy||networkBusy)return;if(e.code==='Space'){e.preventDefault();if(round.phase==='question')speak(round.card.english,{first:waitingForAudio});return;}if(round.phase!=='question'){if(e.key==='Enter'){e.preventDefault();nextRound().catch(e=>toast(e.message));}return;}if(round.mode==='choice'&&/^[1-4]$/.test(e.key)){e.preventDefault();submitAnswer(round.options[Number(e.key)-1]);}else if(round.mode==='spell'){if(e.key==='Backspace'){e.preventDefault();round.selected.pop();updateQuestion();}else if(/^[a-zA-Z-]$/.test(e.key)){e.preventDefault();const tile=round.letters.find(t=>t.letter===e.key.toLowerCase()&&!round.selected.includes(t.id));if(tile)chooseLetter(tile.id);}}});
document.addEventListener('visibilitychange',()=>{sound.setVisible(!document.hidden);if(document.hidden){stopSpeech();if(view==='game'&&!modal.open)pause();}});
try{const responses=await Promise.all(['data/vocabulary.json','data/monsters.json','config.json'].map(p=>fetch(p)));if(responses.some(r=>!r.ok))throw Error('Game files could not load.');[data,MONSTERS]=await Promise.all(responses.slice(0,2).map(r=>r.json()));cloud=new RangerCloud(await responses[2].json());settings.groupIds=Array.isArray(settings.groupIds)?settings.groupIds.filter(id=>data.groups.some(g=>g.id===id)):[];if(!['ALL','CET','FET'].includes(settings.course))settings.course='ALL';if(!['choice','spell','mixed'].includes(settings.mode))settings.mode='mixed';if(![15,25,40].includes(settings.seconds))settings.seconds=25;if(!['all','custom'].includes(settings.scope))settings.scope='all';renderAuth();}catch(e){app.innerHTML=`<main class="error-box"><h1>The island is loading</h1><p>${esc(e.message)}</p><button onclick="location.reload()" class="next-button">Reload</button></main>`;}
